param(
  [string]$TestDirectory = (Join-Path (Split-Path $PSScriptRoot -Parent) '.deps/function-logging-test'),
  [ValidateRange(2,30)][int]$Rounds = 8,
  [ValidateRange(10000,50000000)][int]$Iterations = 2000000
)
$ErrorActionPreference = 'Stop'
$TestDirectory = (Resolve-Path -LiteralPath $TestDirectory).Path
$rows = [Collections.Generic.List[object]]::new()
$pairs = [Collections.Generic.List[object]]::new()
$hashes = [ordered]@{}
foreach ($architecture in @('x86','x64')) {
  foreach ($variant in @('current','old-signature')) {
    $directory = Join-Path $TestDirectory "$variant-$architecture"
    foreach ($file in @('function-logging.exe','function_logging_production.h','function_logging_production.inc')) {
      $hashes["$variant-$architecture/$file"] = (Get-FileHash -LiteralPath (Join-Path $directory $file) -Algorithm SHA256).Hash
    }
  }
}
$processors = @()
try { $processors = @(Get-CimInstance Win32_Processor | Select-Object -ExpandProperty Name) } catch { }
[ordered]@{
  started_utc = [DateTime]::UtcNow.ToString('o')
  processor_names = $processors
  logical_processors = [Environment]::ProcessorCount
  operating_system = [Environment]::OSVersion.VersionString
  rounds = $Rounds
  iterations = $Iterations
  hashes_sha256 = $hashes
  measurement = 'Extracted production logger class, macros, constructor and destructor with disabled log options; separate translation units, /O2 /MT DEBUGOPT; 25000-call warmup. Configuration getters and log sink are adapters; crash-observation and IPC API-entry scopes are no-op adapters. No IPC work is measured. Global operator new counts allocations in a separate loop after timing; counting is disabled during timing.'
  interpretation = 'Adjacent paired runs alternate current/old-signature order. Positive time reduction favors current. Both variants use the same replacement operator new; this isolated allocation/call benchmark is not game FPS or a prediction of FPS gain.'
} | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $TestDirectory 'benchmark-environment.json') -Encoding UTF8
foreach ($architecture in @('x86','x64')) {
  for ($round = 1; $round -le $Rounds; ++$round) {
    $variants = if ($round % 2) { @('current','old-signature') } else { @('old-signature','current') }
    foreach ($variant in $variants) {
      $exe = Join-Path $TestDirectory "$variant-$architecture/function-logging.exe"
      $output = @(& $exe --benchmark $Iterations)
      if ($LASTEXITCODE -ne 0) { throw "Function logging benchmark failed: $variant $architecture" }
      $result = ($output -join "`n") | ConvertFrom-Json
      if ($result.iterations -ne $Iterations) { throw 'Unexpected benchmark iteration count' }
      if ($variant -eq 'current' -and $result.allocations -ne 0) { throw 'Optimized disabled logger allocated' }
      if ($variant -eq 'old-signature' -and $result.allocations -lt $Iterations) { throw 'Old-signature control did not allocate' }
      $result | Add-Member -NotePropertyMembers @{ architecture=$architecture; variant=$variant; round=$round }
      $rows.Add($result)
      Write-Host ("{0} pair {1} {2}: {3:N2} ns/call, {4} allocations" -f $architecture,$round,$variant,$result.ns_per_call,$result.allocations)
    }
    $current = $rows | Where-Object { $_.architecture -eq $architecture -and $_.round -eq $round -and $_.variant -eq 'current' }
    $old = $rows | Where-Object { $_.architecture -eq $architecture -and $_.round -eq $round -and $_.variant -eq 'old-signature' }
    $pairs.Add([pscustomobject]@{
      architecture=$architecture; round=$round
      current_ns_per_call=$current.ns_per_call; old_ns_per_call=$old.ns_per_call
      time_reduction_percent=100 * (1 - $current.ns_per_call / $old.ns_per_call)
      allocations_removed=$old.allocations - $current.allocations
    })
    $rows | Export-Csv -LiteralPath (Join-Path $TestDirectory 'benchmark-results.csv') -NoTypeInformation -Encoding UTF8
    ConvertTo-Json -InputObject @($rows.ToArray()) -Depth 4 | Set-Content -LiteralPath (Join-Path $TestDirectory 'benchmark-results.json') -Encoding UTF8
    $pairs | Export-Csv -LiteralPath (Join-Path $TestDirectory 'benchmark-pairs.csv') -NoTypeInformation -Encoding UTF8
  }
}
